// To make ManyChatControlQuickBoardPlugin runnable:
// Ensure QuickBoardComponent exists and functions as described
// src/components/dashboard/quickboard/QuickBoardComponent.tsx
import React from 'react';
import { Minimize2 } from 'lucide-react'; // Maximize2, PlusCircle, ChevronRight not used here
// Assuming RenderMainContentParams is available globally or correctly imported
// For simplicity, let's define the expected type for showCustomModal
type ShowCustomModalType = (content: React.ReactNode, title?: string) => void;

import { QuickBoardPlugin } from './types';

interface QuickBoardComponentProps {
  showCustomModal: ShowCustomModalType;
  plugins: QuickBoardPlugin[];
  userRoles: string[];
}

const QuickBoardComponent: React.FC<QuickBoardComponentProps> = ({ showCustomModal, plugins, userRoles }) => {
  const authorizedPlugins = plugins.filter(plugin =>
    plugin.roles.some(role => userRoles.includes(role))
  );

  if (authorizedPlugins.length === 0) {
    return (
      <div className="p-6 text-center text-gray-500">
        <p>No Quick Board items available for your role.</p>
      </div>
    );
  }

  return (
    <div className="flex flex-col gap-6 p-4 md:p-6"> {/* Added padding for overall component */}
      {/* Using a single grid for all authorized plugins.
          If you need different layouts for different plugins,
          you might add a 'layoutType' to QuickBoardPlugin
          and have separate maps or conditional rendering. */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {authorizedPlugins.map(plugin => (
            <div key={plugin.id} className="bg-white rounded-lg shadow-md overflow-hidden"> {/* Added overflow-hidden */}
              <div className="p-4 border-b flex justify-between items-center bg-gray-50"> {/* Added bg-gray-50 for header */}
                <h2 className="font-semibold text-gray-700">{plugin.title}</h2>
                <div className="flex gap-1">
                  {/* Example: Minimize button could show plugin content in a modal
                       or perform another action. Here it shows a placeholder. */}
                  <button
                    onClick={() => showCustomModal(
                      <div>
                        <p>Content for {plugin.title} could be displayed here in a modal.</p>
                        <p>This could be a different view or settings for the plugin.</p>
                      </div>,
                      `Options for ${plugin.title}`
                    )}
                    className="p-1 rounded hover:bg-gray-200 text-gray-600" // Adjusted hover
                    title={`More options for ${plugin.title}`}
                  >
                    <Minimize2 size={16} />
                  </button>
                  {/* Add other generic plugin controls here if needed, e.g., refresh, help */}
                </div>
              </div>
              <div className="p-4">
                {/* Pass showCustomModal to the plugin, so it can also trigger modals */}
                <plugin.component showCustomModal={showCustomModal} />
              </div>
            </div>
          ))}
      </div>
    </div>
  );
};

export default QuickBoardComponent;